      "quote": "The Company strictly ensures that all employees are entitled to statutory benefits, including social insurance and the housing fund, annual leave, and sick leave, so that every employee receives consistent care and protection.",
      "kind": "policy",
      "period": "January 1, 2025, to December 31, 2025",
      "scope": "all employees",
      "relevance": "明确披露了法定社会保障（社保、公积金）及基本福利政策。"
    },
    {
      "ref_id": "p003",
      "group_ids": [
        "W2"
      ],
      "quote": "The Company provides employees with commercial insurance coverage above the market average and also offers medical insurance and free vaccinations for employees' children.",
      "kind": "action",
      "period": "January 1, 2025, to December 31, 2025",
      "scope": "employees and their children",
      "relevance": "披露了具体的补充福利安排（商业保险、子女医疗/疫苗）。"
    },
    {
      "ref_id": "p005",
      "group_ids": [
        "W3"
      ],
      "quote": "The Company has established a 24/7 psychological support hotline and launched EAP psychological courses to safeguard employees' mental health.",
      "kind": "action",
      "period": "January 1, 2025, to December 31, 2025",
      "scope": "employees",
      "relevance": "披露了面向员工的家庭与生活支持资源（心理热线、EAP课程）。"
    },
    {
      "ref_id": "p006",
      "group_ids": [
        "W4"
      ],
      "quote": "The Company also provides assistance to employees in financial hardship by granting monthly subsidies to eligible employees and offers home visits and condolence payments to employees suffering from serious illness.",
      "kind": "mechanism",
      "period": "January 1, 2025, to December 31, 2025",
      "scope": "eligible employees / employees suffering from serious illness",
      "relevance": "披露了福利的具体取得规则或适用对象（符合条件员工获月度补贴，重病员工获慰问金）。"
    },
    {
      "ref_id": "p001",
      "group_ids": [
        "W5"
      ],
      "quote": "In 2025, the total value of employee benefits distributed by the Company amounted to RMB 73.12 million.",
      "kind": "result",
      "period": "2025",
      "scope": "Company",
      "relevance": "披露了当期已发生的福利发放事实（总金额），证明实际覆盖与使用。"
